package android.graphics;public class BitmapFactory {public static class Options {public boolean inJustDecodeBounds,inScaled;public int outWidth,outHeight,inSampleSize;public Bitmap.Config inPreferredConfig;}public static int[] original(int marker){if(marker==4)return new int[]{1080,3000};if(marker==5)return new int[]{2560,1440};if(marker==6)return new int[]{160,90};if(marker==7)return new int[]{1081,3001};return new int[]{10,10};}public static Bitmap decodeByteArray(byte[] bytes,int offset,int count,Options options){int[] size=original(bytes[offset]&255);options.outWidth=size[0];options.outHeight=size[1];if(options.inJustDecodeBounds)return null;int sample=Math.max(1,options.inSampleSize);Bitmap bitmap=new Bitmap((size[0]+sample-1)/sample,(size[1]+sample-1)/sample);options.outWidth=bitmap.getWidth();options.outHeight=bitmap.getHeight();return bitmap;}}
